import { test as check } from 'node:test';
import { equal, deepEqual, ok } from 'node:assert/strict';
import { WeightedCache } from '../src/lru.ts';
import { PartitionedCache } from '../src/partition.ts';
import { singleFlight, memoize } from '../src/memo.ts';
import { RecencyList } from '../src/list.ts';
check('weighted eviction follows recent access and expiration', () => {
  let clock = 0;
  const cache = new WeightedCache(100, () => clock);
  cache.set('a', 1, 10, 20);
  cache.set('b', 2, 10, 40);
  equal(cache.get('a'), 1);
  cache.set('c', 3, 10, 50);
  deepEqual(cache.keys(), ['c', 'a']);
  clock = 25;
  equal(cache.get('a'), undefined);
  ok(cache.verify());
  const tenants = new PartitionedCache(100, () => clock);
  tenants.write('one', 'key', 1, 1);
  tenants.write('two', 'key', 2, 1);
  equal(tenants.read('two', 'key'), 2);
  equal(tenants.clearKey('key'), 2);
});
check('list promotion and concurrent computation preserve identity', async () => {
  const list = new RecencyList();
  const a = list.prepend('a');
  list.prepend('b');
  list.promote(a);
  deepEqual([...list.keys()], ['a', 'b']);
  ok(list.verify());
  let computations = 0;
  const get = singleFlight(async (key) => { computations++; return key.length; });
  deepEqual(await Promise.all([get('same'), get('same')]), [4, 4]);
  equal(computations, 1);
  const memo = memoize((key) => key * key, 2);
  equal(memo(4), 16);
  equal(memo(4), 16);
  equal(memo.size(), 1);
});

